import{_ as o,c,o as t,b2 as d}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"C7TreeSelect 树形选择器","description":"","frontmatter":{},"headers":[],"relativePath":"docs/frontend/components/通用组件/c7-tree-select.md","filePath":"docs/frontend/components/通用组件/c7-tree-select.md"}'),a={name:"docs/frontend/components/通用组件/c7-tree-select.md"};function r(l,e,s,n,i,p){return t(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="c7treeselect-树形选择器" tabindex="-1">C7TreeSelect 树形选择器 <a class="header-anchor vp-link" href="#c7treeselect-树形选择器" aria-label="Permalink to &quot;C7TreeSelect 树形选择器&quot;">​</a></h1><p>在 <strong><code>ElTreeSelect</code></strong> 上封装 <strong>静态/异步整树</strong>、<strong>字段映射</strong>、<strong>多选 <code>separator</code> 逗号串</strong> 与 <strong><code>valueType</code></strong>，契约对齐 <strong><code>C7Select</code></strong>（<code>dataList</code>/<code>options</code>、<code>fetchData</code>、<code>resultKey</code>、<code>dataFormatter</code>、<code>autoLoad</code>）。</p><p><strong>源码</strong>：<code>quick-ui/src/packages/C7TreeSelect/index.vue</code></p><h2 id="功能概要" tabindex="-1">功能概要 <a class="header-anchor vp-link" href="#功能概要" aria-label="Permalink to &quot;功能概要&quot;">​</a></h2><ul><li><strong>数据</strong>：<code>dataList</code> 优先于 <code>options</code>；无静态绑定时 <code>fetchData</code> + <code>resultKey</code>（可选 <code>dataFormatter</code>）拉取整树。</li><li><strong>映射</strong>：<code>labelKey</code> / <code>valueKey</code> / <code>childrenKey</code>（默认 <code>label</code>/<code>value</code>/<code>children</code>），内部规范为 EP 树节点。</li><li><strong>多选</strong>：<code>multiple</code>；<code>separator</code> 为 true 时对外为逗号字符串，空为 <code>&#39;&#39;</code>。</li><li><strong><code>valueType</code></strong>：<code>auto</code> | <code>string</code> | <code>number</code>；<code>auto</code> 由<strong>映射后根列表首节点</strong>的 <code>value</code> 类型推断。</li><li><strong>透传</strong>：<code>filterable</code>、<code>filter-node-method</code> 等未占用键通过 attrs 透传至 <code>ElTreeSelect</code>。</li><li><strong>事件</strong>：<code>update:modelValue</code>、<code>change</code>、<code>load-error</code>、<code>visible-change</code>、<code>loading-change</code>。</li><li><strong>方法</strong>：<code>reload()</code>（静态时重新同步内外值；异步时重新 <code>fetchData</code>）。</li></ul><h2 id="与全局注册" tabindex="-1">与全局注册 <a class="header-anchor vp-link" href="#与全局注册" aria-label="Permalink to &quot;与全局注册&quot;">​</a></h2><p><code>main.js</code> 调用 <code>installPackages(app)</code> 后，可使用 <code>&lt;c7-tree-select /&gt;</code> / <code>&lt;C7TreeSelect /&gt;</code>。</p><h2 id="限制" tabindex="-1">限制 <a class="header-anchor vp-link" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h2><ul><li>若多选 value 本身含英文逗号，<strong>勿</strong>使用 <code>separator</code> 模式（与 <code>C7Select</code> 相同）。</li><li>一期不支持节点 <code>lazy</code> 远程懒加载（见设计说明）。</li></ul><h2 id="相关规格" tabindex="-1">相关规格 <a class="header-anchor vp-link" href="#相关规格" aria-label="Permalink to &quot;相关规格&quot;">​</a></h2><ul><li>设计说明（仓库内）：<code>docs/superpowers/specs/2026-05-07-c7-tree-select-design.md</code></li><li>OpenSpec 变更：<code>openspec/changes/ui-c7-tree-select/specs/ui-c7-tree-select/spec.md</code></li></ul>',11)])])}const h=o(a,[["render",r]]);export{u as __pageData,h as default};
